  en: { title: 'Presentations', lead: 'Presentations need clear flow and recurring slide patterns so teams can work consistently and quickly.', sections: [{ id: 'slide-types', title: 'Slide Types', items: ['Title slide.', 'Section divider.', 'Text and image slide.', 'Quote slide.', 'Closing slide with contact or call to action.'] }, { id: 'rules', title: 'Rules', items: ['One idea per slide.', 'Large type and little body copy.', 'Simplify charts and keep axes readable.', 'Do not overemphasise logo and sender on every slide.'] }, { id: 'examples', title: 'Strong and Weak Examples', items: [{ label: 'Strong:', text: ' a title slide uses a short statement, generous space and a clear Volt colour surface, so topic and sender are immediately recognisable.' }, { label: 'Weak:', text: ' one slide contains body copy, three charts and several messages; fix by splitting the content across slides and prioritising one statement per slide.' }, { label: 'Strong:', text: ' a chart reduces data to the core message, keeps axes readable and explains the takeaway in a short headline.' }, { label: 'Weak:', text: ' an image sits uncropped in the background and the text loses contrast; fix with a calm surface, clear crop and contrast check.' }] }, { id: 'tools', title: 'Tools', items: ['Figma for master design and complex templates.', 'Canva for simple adaptation by teams.', 'PowerPoint or Google Slides only with checked export quality.'] }] },
