  fr: { title: 'Présentations', lead: 'Les présentations ont besoin d’une narration claire et de modèles de slides récurrents pour permettre un travail rapide et cohérent.', sections: [{ id: 'types-slides', title: 'Types de slides', items: ['Slide titre.', 'Séparateur de chapitre.', 'Slide texte et image.', 'Slide citation.', 'Slide finale avec contact ou appel à l’action.'] }, { id: 'regles', title: 'Règles', items: ['Une idée par slide.', 'Grande typographie et peu de texte courant.', 'Simplifier les graphiques et garder les axes lisibles.', 'Ne pas suraccentuer logo et émetteur sur chaque slide.'] }, { id: 'exemples', title: 'Bons et mauvais exemples', items: [{ label: 'Bon :', text: ' une slide titre utilise un message court, beaucoup d’espace et un aplat Volt clair, ce qui rend le sujet et l’émetteur immédiatement reconnaissables.' }, { label: 'Problématique :', text: ' une slide contient du texte courant, trois graphiques et plusieurs messages ; corriger en répartissant le contenu sur plusieurs slides et en priorisant une idée par slide.' }, { label: 'Bon :', text: ' un graphique réduit les données au message central, garde les axes lisibles et explique la conclusion dans un titre court.' }, { label: 'Problématique :', text: ' une image non recadrée sert de fond et le texte perd du contraste ; corriger avec un aplat calme, un recadrage clair et une vérification du contraste.' }] }, { id: 'outils', title: 'Outils', items: ['Figma pour master design et modèles complexes.', 'Canva pour adaptation simple par les équipes.', 'PowerPoint ou Google Slides seulement avec qualité d’export vérifiée.'] }] },
